let __v_1 = pyrt::literals::decode("{\"$dict\":[[\"rice cooker\",{\"$tuple\":[\"without\",\"no\",\"dont\",\"don't\",\"havent\",\"haven't\"]}],[\"buttermilk\",{\"$tuple\":[\"make\",\"making\",\"makes\",\"substitute\",\"instead\",\"without\",\"no\",\"dont\",\"don't\",\"havent\",\"haven't\",\"don't have\",\"replace\",\"swap\",\"keeps\",\"keep\",\"store\",\"storing\",\"freeze\",\"freezer\",\"frozen\"]}],[\"vegetables\",{\"$tuple\":[\"grow\",\"plant\",\"garden\",\"allotment\",\"juice\",\"smoothie\",\"frozen\",\"tin\",\"more\",\"eat\",\"eating\",\"eaten\",\"fussy\",\"kids\",\"children\",\"family\",\"diet\",\"calories\",\"portion\",\"portions\",\"serving\",\"servings\"]}],[\"onions\",{\"$tuple\":[\"pickled\",\"raw\",\"rings\",\"spring\",\"red onion\",\"shallot\",\"soup\",\"stuffed\",\"bhaji\",\"chutney\",\"cry\",\"crying\",\"eyes\",\"smell\",\"smells\",\"smelly\",\"stink\",\"stinks\",\"fridge\",\"freezer\",\"frozen\",\"keeping\",\"keep\",\"store\",\"storing\"]}],[\"chop an onion\",{\"$tuple\":[\"cry\",\"crying\",\"tears\",\"eyes\",\"pickled\",\"raw\",\"rings\",\"ring\",\"spring\",\"red onion\",\"shallot\",\"soup\",\"stuffed\",\"bhaji\",\"chutney\",\"smell\",\"smells\",\"smelly\",\"stink\",\"stinks\",\"fridge\",\"freezer\",\"frozen\",\"keep\",\"keeping\",\"store\",\"storing\",\"grow\",\"plant\",\"caramelise\",\"caramelize\",\"soften\",\"sweet\",\"french onion\"]}],[\"peel a potato\",{\"$tuple\":[\"grow\",\"plant\",\"boil\",\"roast\",\"bake\",\"mash\",\"chip\",\"chips\",\"watery\",\"sprout\",\"sprouts\",\"green\",\"eyes\",\"salad\",\"soup\",\"gnocchi\",\"freezer\",\"frozen\",\"store\",\"keeping\",\"keep\",\"brown\",\"browning\"]}],[\"chop garlic\",{\"$tuple\":[\"bread\",\"butter\",\"grow\",\"plant\",\"smell\",\"smells\",\"smelly\",\"breath\",\"hands\",\"press\",\"roast\",\"sauce\",\"aioli\",\"mayo\",\"mayonnaise\",\"powder\",\"granules\",\"store\",\"keep\",\"freezer\",\"frozen\",\"sprout\",\"sprouts\"]}],[\"peel ginger\",{\"$tuple\":[\"tea\",\"grow\",\"plant\",\"powder\",\"ground\",\"biscuit\",\"bread\",\"cake\",\"beer\",\"ale\",\"pickled\",\"sushi\",\"store\",\"keep\",\"freezer\",\"frozen\",\"root\"]}],[\"chop a carrot\",{\"$tuple\":[\"boil\",\"roast\",\"grow\",\"plant\",\"soup\",\"cake\",\"muffin\",\"raw\",\"salad\",\"stick\",\"sticks\",\"batons\",\"freezer\",\"frozen\",\"store\",\"keep\"]}],[\"chop mushrooms\",{\"$tuple\":[\"pizza\",\"stuffed\",\"garlic\",\"toast\",\"pasta\",\"soup\",\"risotto\",\"pie\",\"grow\",\"pick\",\"wild\",\"forage\",\"freezer\",\"frozen\",\"dried\",\"dry\",\"raw\",\"eat\",\"store\",\"keep\",\"slimy\",\"gone off\"]}],[\"cut an avocado\",{\"$tuple\":[\"toast\",\"salad\",\"guacamole\",\"ripen\",\"ripe\",\"brown\",\"browning\",\"store\",\"keep\",\"freezer\",\"frozen\",\"smoothie\",\"plant\",\"tree\",\"grow\",\"sushi\",\"calories\",\"healthy\",\"good for\"]}],[\"peel a mango\",{\"$tuple\":[\"juice\",\"smoothie\",\"chutney\",\"dried\",\"ripen\",\"ripe\",\"grow\",\"tree\",\"salad\",\"salsa\",\"sticky\",\"ice cream\",\"store\",\"keep\",\"freezer\"]}],[\"cut up a pineapple\",{\"$tuple\":[\"pizza\",\"juice\",\"upside\",\"cake\",\"grow\",\"plant\",\"skin\",\"coconut\",\"tin\",\"can\",\"ring\",\"rings\",\"dried\",\"ripen\",\"ripe\",\"store\",\"keep\",\"freezer\",\"frozen\"]}],[\"juice a lemon\",{\"$tuple\":[\"cake\",\"drizzle\",\"curd\",\"preserve\",\"pickle\",\"tree\",\"grow\",\"plant\",\"water\",\"detox\",\"morning\",\"hot\",\"tea\",\"store\",\"keep\",\"freezer\",\"peel\",\"zest\"]}],[\"corn on the cob\",{\"$tuple\":[\"popcorn\",\"flour\",\"starch\",\"syrup\",\"tin\",\"can\",\"kernels\",\"fritter\",\"chowder\",\"bread\"]}],[\"butternut squash\",{\"$tuple\":[\"soup\",\"risotto\",\"seeds\",\"grow\",\"plant\",\"carve\",\"pumpkin\"]}],[\"broad beans\",{\"$tuple\":[\"soak\",\"soaks\",\"soaking\",\"soaked\",\"overnight\",\"dried\",\"dry\",\"dries\",\"tinned\",\"canned\",\"tin\",\"can\",\"bag\",\"packet\"]}],[\"pork chops\",{\"$tuple\":[\"slow cooker\",\"casserole\",\"apple\",\"cider\",\"butterfly\",\"cheap\"]}],[\"fish\",{\"$tuple\":[\"tank\",\"tanks\",\"aquarium\",\"fish tank\",\"fishbowl\",\"fish bowl\",\"gravel\",\"filter\",\"dechlorinator\",\"fish and chips\",\"fish fingers\",\"pond\",\"pet\",\"smell\",\"smells\",\"smelly\",\"shellfish\",\"allergy\",\"market\",\"monger\",\"batter\",\"smoke\",\"smoked\",\"smoking\",\"cure\",\"cured\",\"gravad\",\"gravlax\",\"kipper\",\"kippers\",\"cat\",\"cats\",\"dog\",\"dogs\",\"raw\",\"sashimi\",\"sushi\",\"stock\",\"sauce\",\"pie\",\"cakes\",\"fishcake\",\"fishcakes\",\"frozen\",\"freezer\",\"thaw\",\"defrost\",\"leftover\",\"leftovers\",\"more\",\"eat\",\"eating\",\"eaten\",\"portion\",\"portions\",\"serving\",\"servings\",\"twice\",\"week\",\"healthy\",\"oily\"]}]]}")?;
