let __v_10 = pyrt::literals::decode("{\"$dict\":[[\"chocolate cake\",{\"$tuple\":[{\"$tuple\":[\"chocolate cake\",\"chocolate sponge\",\"chocolate gateau\"]},\"Equal weights of everything: for a 20cm tin, 200g each of soft butter, caster sugar, eggs and self-raising flour, with 50g of the flour swapped for cocoa. Cream the butter and sugar, beat the eggs in one at a time, fold in the flour and cocoa, then bake at 180C (160C fan) for 25 to 30 minutes, until a skewer comes out clean.\"]}],[\"victoria sponge\",{\"$tuple\":[{\"$tuple\":[\"victoria sponge\",\"sponge cake\",\"victoria sandwich\",\"plain sponge\"]},\"Weigh the eggs and use the same weight of soft butter, caster sugar and self-raising flour: three eggs fills two 20cm tins. Cream butter and sugar, beat the eggs in a spoonful at a time, fold in the flour, split between the tins and bake at 180C (160C fan) for 20 to 25 minutes, then sandwich with jam and whipped cream.\"]}],[\"brownies\",{\"$tuple\":[{\"$tuple\":[\"brownies\",\"brownie\",\"chocolate brownies\"]},\"Melt 200g dark chocolate with 180g butter, beat in 250g sugar and 3 eggs, then fold in 100g plain flour and a pinch of salt. Bake in a lined 20cm square tin at 180C (160C fan) for 20 to 25 minutes: the middle should still be a little soft when you take it out, and it sets as it cools.\"]}],[\"scones\",{\"$tuple\":[{\"$tuple\":[\"scones\",\"scone\",\"cheese scones\"]},\"350g self-raising flour, 2 teaspoons baking powder, 85g cold butter rubbed in, then 3 tablespoons of sugar and about 150ml milk to bring it together - handle it as little as you can. Cut into rounds, brush with milk and bake at 220C (200C fan) for 12 to 15 minutes, until risen and golden.\"]}],[\"bread\",{\"$tuple\":[{\"$tuple\":[\"white bread\",\"bread\",\"loaf of bread\",\"bread dough\",\"loaf\"]},\"500g strong white flour, 7g dried yeast, 10g salt and 350ml warm water, kneaded for 10 minutes until smooth and stretched. Leave it somewhere warm for an hour until doubled, knock it back, shape it into a tin, leave it 45 minutes more, then bake at 220C (200C fan) for 30 minutes - it is done when it sounds hollow underneath.\"]}],[\"banana bread\",{\"$tuple\":[{\"$tuple\":[\"banana bread\",\"banana loaf\"]},\"Three very ripe bananas mashed with 150g soft brown sugar, 2 eggs and 100g melted butter, then 250g self-raising flour and a teaspoon of cinnamon folded in. Bake in a lined loaf tin at 170C (150C fan) for 55 to 60 minutes; a skewer in the middle should come out with crumbs, not batter.\"]}],[\"flapjack\",{\"$tuple\":[{\"$tuple\":[\"flapjack\",\"flapjacks\"]},\"Melt 150g butter with 120g golden syrup and 120g soft brown sugar, stir in 300g porridge oats, press into a lined 20cm square tin and bake at 180C (160C fan) for 20 to 25 minutes. Leave it in the tin until it is completely cold, or it will not cut.\"]}],[\"cookies\",{\"$tuple\":[{\"$tuple\":[\"cookies\",\"cookie\",\"chocolate chip cookies\",\"biscuits\"]},\"Cream 125g soft butter with 100g sugar, beat in 1 egg, then stir in 175g plain flour, half a teaspoon of bicarbonate of soda and 100g chocolate chips. Roll into balls, space them well apart on a lined tray and bake at 180C (160C fan) for 10 to 12 minutes - they firm up as they cool.\"]}],[\"crumble\",{\"$tuple\":[{\"$tuple\":[\"crumble\",\"fruit crumble\",\"apple crumble\"]},\"Rub 100g cold butter into 200g plain flour with 75g sugar until it looks like breadcrumbs, then scatter it over fruit with a spoon of sugar on top. Bake at 190C (170C fan) for 35 to 40 minutes, until the fruit bubbles at the edges and the top is golden.\"]}],[\"puff pastry\",{\"$tuple\":[{\"$tuple\":[\"puff pastry\",\"puff pastry sheet\",\"ready rolled puff pastry\"]},\"Puff pastry: a sheet with the filling already cooked and cooled goes in at 200C (180C fan) for 25 to 30 minutes, and one brushed with beaten egg browns better. Score the top so the steam gets out.\"]}],[\"shortcrust pastry\",{\"$tuple\":[{\"$tuple\":[\"shortcrust pastry\",\"pie crust\",\"pastry\"]},\"Half the fat to flour by weight: 250g plain flour and 125g cold butter rubbed in with a pinch of salt, then a few spoons of cold water to bring it together. Rest it in the fridge 30 minutes before rolling, and bake blind at 190C (170C fan) for 15 minutes for a flan case.\"]}],[\"sourdough bread\",{\"$tuple\":[{\"$tuple\":[\"sourdough bread\",\"sourdough loaf\",\"sour dough bread\",\"sourdough\"]},\"Sourdough is a starter, not dried yeast: 100g of fed starter to 500g strong flour and about 350ml water, mixed and left 4 to 6 hours with a fold every hour until it is puffy, then shaped and proved in the fridge overnight. Bake it at 250C in a lidded pot for 20 minutes with the lid on and 20 to 25 with it off. A starter takes about a week of feeding before it will raise a loaf, so this is a plan for next weekend rather than tonight.\"]}],[\"wholemeal bread\",{\"$tuple\":[{\"$tuple\":[\"wholemeal bread\",\"wholewheat bread\",\"whole wheat bread\",\"wholemeal loaf\",\"brown bread\",\"granary loaf\"]},\"Use 300g wholemeal flour with 200g strong white, 7g dried yeast, 10g salt and about 380ml warm water: wholemeal drinks more, so it wants a wetter dough than white. Leave it 2 to 3 hours until it has doubled rather than 1 to 2, prove the shaped loaf 45 minutes, then bake at 220C (200C fan) for 35 to 40 minutes.\"]}],[\"bread maker loaf\",{\"$tuple\":[{\"$tuple\":[\"bread maker\",\"breadmaker\",\"bread machine\"]},\"Put the water in the pan first, then the flour, then the salt in one corner and the yeast in the other so the salt never sits on the yeast, and set the basic white programme. 500g of flour and 7g of yeast fits a standard 1.5kg machine, and taking the loaf out about 5 minutes before the end keeps the crust from going soft in the pan.\"]}],[\"gluten free bread\",{\"$tuple\":[{\"$tuple\":[\"gluten free bread\",\"gluten-free bread\",\"gluten free loaf\",\"gf bread\"]},\"Buy a gluten-free bread blend with a binder in it rather than swapping the flour in a normal recipe, which gives a brick: the dough is more like a thick batter, so it goes straight into the tin and gets one rise, then 40 to 45 minutes at 200C (180C fan). Let it cool fully before you slice it, or it crumbles.\"]}]]}")?;
